// POLL_PERF
NV_DECLARE_ALIGNED(RUSD_PERF_CURRENT_PSTATE perfCurrentPstate, 8);

static inline NvBool
RusdIsSeqValid
(
    NvU64 seq
)
{
    return ((seq >= RUSD_SEQ_START) && !(seq & 0x1llu)) ||
        (seq < RUSD_SEQ_START && 
         seq != RUSD_TIMESTAMP_INVALID &&
         seq != RUSD_TIMESTAMP_WRITE_IN_PROGRESS);
}

